import os,re,itertools
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def f(I):
    H,W=len(I),len(I[0])
    cnt=Counter(v for row in I for v in row)
    bg=cnt.most_common(1)[0][0]
    sepv=max((k for k,v in cnt.items() if k!=bg), key=lambda k: sum(1 for row in I for x in row if x==k))
    seps_r=[i for i in range(H) if all(x==sepv for x in I[i])]
    seps_c=[j for j in range(W) if all(I[i][j]==sepv for i in range(H))]
    def blk(seps,N):
        bs=[]; s=-1
        for e in seps+[N]:
            if e-s>1: bs.append((s+1,e-1)); s=e
        return bs
    br=blk(seps_r,H); bc=blk(seps_c,W)
    mark=[c for c in cnt if c not in (bg,sepv)][0]
    out=[row[:] for row in I]
    best=None;bestn=-1
    for r0,r1 in br:
        for c0,c1 in bc:
            n=sum(1 for r in range(r0,r1+1) for c in range(c0,c1+1) if I[r][c]==mark)
            if n>bestn: bestn=n; best=(r0,r1,c0,c1)
    if best:
        r0,r1,c0,c1=best
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): out[r][c]=mark
    return out
